PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE participants (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  participant_key TEXT NOT NULL UNIQUE,
  user_id TEXT,
  session_id TEXT,
  prolific_pid TEXT,
  study_id TEXT,
  prolific_session_id TEXT,
  app_version TEXT,
  first_seen_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  event_count INTEGER NOT NULL DEFAULT 0
, final_outcome TEXT, last_event TEXT, last_cycle TEXT, last_attempt_number INTEGER, last_turn INTEGER, last_progress_at INTEGER, difficulty_seed INTEGER, win_threshold_scalars TEXT, condition TEXT DEFAULT 'game', wiki_payload TEXT);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_participants_prolific ON participants(prolific_pid);
CREATE INDEX idx_participants_condition ON participants(condition);
